using System.Linq;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
public sealed class NarrativePlayModeChecks:MonoBehaviour
{
 [Serializable]public class Result{public bool finished,passed;public string error;public List<string> checks=new List<string>();}public Result report=new Result();
 BedroomPhaseController p;BedroomGameUI ui;NightIntroductionController intro;CorpseEncounterController corpse;BedroomEncounterDirector director;Keyboard keyboard;Mouse mouse;InputSettings oldInput,testInput;float oldSpeed;int events;
 void Check(bool ok,string label){report.checks.Add((ok?"PASS: ":"FAIL: ")+label);if(!ok)throw new Exception(label);}
 void Key(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));}
 IEnumerator Keys(params Key[] keys){Key(keys);yield return null;yield return null;}
 IEnumerator Click(){InputSystem.QueueStateEvent(mouse,new MouseState().WithButton(MouseButton.Left));yield return null;yield return null;InputSystem.QueueStateEvent(mouse,new MouseState());yield return null;}
 IEnumerator Wait(Func<bool> condition,float timeout=15){float until=Time.realtimeSinceStartup+timeout;while(!condition()&&Time.realtimeSinceStartup<until)yield return null;if(!condition())throw new Exception("Timed out: phase="+p.State+" corpse="+corpse.State+" line="+ui.DialogueLineIndex);}
 IEnumerator Aim(Vector3 target){p.CaptureCursor();for(int i=0;i<6;i++){if(Vector3.Angle(p.view.transform.forward,target-p.view.transform.position)<1)break;var q=Quaternion.LookRotation(target-p.view.transform.position);InputSystem.QueueDeltaStateEvent(mouse.delta,new Vector2(Mathf.DeltaAngle(p.view.transform.eulerAngles.y,q.eulerAngles.y),-Mathf.DeltaAngle(p.view.transform.eulerAngles.x,q.eulerAngles.x))/p.movement.mouseSensitivity);yield return null;yield return null;}}
 IEnumerator Advance(){yield return new WaitForSecondsRealtime(.12f);yield return Keys(UnityEngine.InputSystem.Key.Enter);yield return Keys();}
 IEnumerator FinishDialogue(){int safety=0;while(ui.DialogueActive&&safety++<100){if(ui.DialogueBusy){yield return null;continue;}yield return Advance();}yield return Wait(()=>p.State==BedroomPhase.NightGameplay);}
 IEnumerator Picture(string name){yield return new WaitForEndOfFrame();var texture=ScreenCapture.CaptureScreenshotAsTexture();System.IO.File.WriteAllBytes("Temp/BedroomPrototype/Narrative/"+name+".png",texture.EncodeToPNG());Destroy(texture);}
 void Reply(){ui.ActiveButtonRoot.GetComponentsInChildren<UnityEngine.UI.Button>().First(b=>b.gameObject.activeSelf&&b!=ui.buttonTemplate).onClick.Invoke();}
 IEnumerator Start()
 {
  p=FindAnyObjectByType<BedroomPhaseController>();ui=p.ui;intro=p.introductions;corpse=p.corpse;director=corpse.director;director.automaticScheduling=false;p.night.nightDurationSeconds=300;oldSpeed=ui.defaultCharactersPerSecond;
  oldInput=InputSystem.settings;testInput=Instantiate(oldInput);testInput.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;testInput.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=testInput;keyboard=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();
  var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){object next=null;bool more=false;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception ex){report.error=ex.ToString();break;}if(!more){stack.Pop();continue;}if(next is IEnumerator nested){stack.Push(nested);continue;}yield return next;}
  Key();InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);InputSystem.settings=oldInput;Destroy(testInput);ui.defaultCharactersPerSecond=oldSpeed;report.finished=true;report.passed=string.IsNullOrEmpty(report.error);System.IO.File.WriteAllText("Temp/BedroomPrototype/Narrative/PlayModeChecks.json",JsonUtility.ToJson(report,true));Debug.Log("Narrative checks: "+report.passed+" "+report.error);
 }
 IEnumerator Run()
 {
  yield return null;yield return null;Check(intro.introductions.Select(s=>s.lines.Length).SequenceEqual(new[]{17,12,15}),"editable assets contain all supplied night dialogue");Check(intro.reveal.SharedFacialIdentity,"corpse and player share the same underlying identity mesh");Check(FindObjectsByType<AudioSource>().Length<=26,"no narrative voice AudioSources were introduced");Check(corpse.reveal.Ready&&corpse.reveal.fragments.Length==12,"existing glass geometry builds reusable fragments");
  var sample=ScriptableObject.CreateInstance<DialogueSequence>();sample.sequenceId="test-generic";sample.lines=new[]{new DialogueLine{speaker="Protagonist",text="I should keep moving.",charactersPerSecond=3},new DialogueLine{speaker="Narration",text="The room waits.",charactersPerSecond=0,eventId="test.flag"}};Vector3 pos=p.movement.transform.position;bool completed=false;ui.dialogueEvent.AddListener(id=>{if(id=="test.flag"){events++;p.tasks.SetStoryFlag("test.flag",true);}});Check(ui.TryShowDialogue(sample,()=>completed=true),"existing UI opens a reusable protagonist/narration sequence");Check(!p.movement.enabled&&ui.ModalOpen,"blocking dialogue owns movement and E interaction mode");Check(!ui.TryShowDialogue(sample),"a second dialogue cannot open over the first");yield return new WaitForSecondsRealtime(.15f);Check(ui.DialogueTyping&&ui.dialogueSpeaker.text=="PROTAGONIST","speaker style and optional typewriter display correctly");yield return Keys(UnityEngine.InputSystem.Key.E,UnityEngine.InputSystem.Key.W);yield return Keys();Check(ui.DialogueLineIndex==0&&Vector3.Distance(pos,p.movement.transform.position)<.01f,"E and WASD cannot leak through blocking dialogue");yield return Click();Check(!ui.DialogueTyping&&ui.DialogueLineIndex==0,"first left click completes text without advancing line");yield return Advance();Check(ui.DialogueLineIndex==1&&ui.dialogueSpeaker.text=="NARRATION","configured keyboard advance moves exactly one line");yield return Advance();Check(completed&&!ui.DialogueActive&&events==1&&p.tasks.GetStoryFlag("test.flag"),"last line closes dialogue, fires explicit event and completion once");yield return null;Check(p.movement.enabled,"previous exploration movement mode is restored");Destroy(sample);
  var condition=new DialogueCondition{day=1,requiredFlag="test.flag",flagValue=true};Check(condition.Matches(p.tasks,p),"simple day/story-flag conditions are supported");condition.day=2;Check(!condition.Matches(p.tasks,p),"unmet dialogue condition is rejected");
