  p.LoseNight();p.RetryNight();yield return null;Check(p.State==BedroomPhase.NightIntroduction&&intro.CanSkip&&!p.night.Running,"retry reuses the same introduction and exposes seen-only skip");yield return Keys(UnityEngine.InputSystem.Key.Tab);yield return Keys();yield return Wait(()=>p.State==BedroomPhase.NightGameplay);Check(FindObjectsByType<NightIntroductionController>().Length==1&&FindObjectsByType<BedroomGameUI>().Length==1,"retry/skip does not duplicate dialogue management");
  intro.DebugStartNight(2);yield return Wait(()=>ui.DialogueActive);Check(ui.CurrentDialogue==intro.introductions[1]&&!p.night.Running,"Night 2 uses its shorter editable introduction");yield return FinishDialogue();Check(!corpse.NightActive&&!corpse.ForceStartEncounter(),"corpse remains passive throughout Night 2");
  intro.DebugStartNight(3);yield return Wait(()=>ui.DialogueActive);Check(ui.CurrentDialogue==intro.introductions[2]&&!corpse.reveal.Finished,"Night 3 begins with remaining glass and the correct dialogue");while(ui.DialogueLineIndex<3)yield return Advance();yield return Advance();Check(corpse.reveal.Cracked&&ui.DialogueBusy,"explicit glass.fracture event starts cracking at the configured line");yield return Wait(()=>!ui.DialogueBusy);Check(ui.DialogueLineIndex==4,"dialogue resumes after the fracture event");yield return Advance();Check(ui.DialogueBusy&&!ui.dialoguePanel.activeSelf,"reveal event temporarily hides the dialogue box");yield return new WaitForSecondsRealtime(.5f);Check(!p.night.Running&&corpse.State==CorpseEncounterState.Dormant,"corpse cannot attack during the reveal animation");yield return Picture("Night3Reveal");yield return Wait(()=>corpse.reveal.Finished,10);yield return Picture("Night3FaceRevealed");yield return Wait(()=>!ui.DialogueBusy,10);Check(corpse.reveal.Finished&&corpse.reveal.fragments.All(r=>!r.enabled)&&ui.dialoguePanel.activeSelf,"glass falls away reversibly and dialogue returns with the body intact");yield return FinishDialogue();Check(corpse.NightActive&&corpse.RemainingDormant>19,"corpse becomes eligible only after Night 3 intro with a 20-second initial delay");Check(director.CurrentSchedule.corpseWeight>0&&director.SelectionBlockedReason(corpse).StartsWith("cooldown"),"existing randomized director includes corpse weight and honors initial delay");
  p.LoseNight();p.RetryNight();yield return null;Check(!corpse.reveal.Finished&&intro.CanSkip,"Night 3 retry restores reveal setup without destroying objects");yield return Keys(UnityEngine.InputSystem.Key.Tab);yield return Keys();yield return Wait(()=>p.State==BedroomPhase.NightGameplay);Check(corpse.reveal.Finished&&corpse.reveal.fragments.All(r=>!r.enabled),"skipped Night 3 intro applies completed reveal before gameplay");
  director.underBed.SetEncountersEnabled(false);director.door.SetEncountersEnabled(false);director.window.SetEncountersEnabled(false);director.quietInterval=.05f;yield return new WaitForSeconds(.1f);yield return Keys(UnityEngine.InputSystem.Key.Q);Check(corpse.ForceStartEncounter(),"Night 3 corpse encounter can be force-started in bed");Check(corpse.State==CorpseEncounterState.Beckoning,"corpse begins with a recognizable Beckoning warning");yield return Wait(()=>corpse.State==CorpseEncounterState.Reaching);yield return Aim(corpse.head.position);yield return new WaitForSeconds(.3f);Check(corpse.State==CorpseEncounterState.Reaching&&corpse.RequiresRelease&&corpse.ResistanceProgress==0,"holding Q before encounter start does not grant protection");Check(corpse.CameraDrop>0&&p.view.transform.position.y<p.nightCameraAnchor.position.y,"reaching adds camera pull without changing the base anchor");yield return Keys();yield return Aim(corpse.head.position);yield return Keys(UnityEngine.InputSystem.Key.Q);yield return Wait(()=>corpse.State==CorpseEncounterState.Resisting);yield return new WaitForSeconds(.3f);Check(corpse.ResistanceProgress>0&&!p.CanUseNightDefenses,"valid Q gaze begins sustained resistance and blocks incompatible defenses");yield return Picture("CorpseResistance");float pull=corpse.PullProgress;yield return Keys();Check(corpse.State==CorpseEncounterState.Reaching&&corpse.ResistanceProgress==0&&corpse.PullProgress>=pull,"early release loses partial resistance instead of allowing a tapping reset exploit");yield return Aim(corpse.head.position);yield return Keys(UnityEngine.InputSystem.Key.Q);yield return Wait(()=>corpse.State==CorpseEncounterState.Retreat);Check(corpse.SuccessfulDefenses==1,"sustained 1.75-second facing-Q resistance succeeds");yield return Keys();yield return Wait(()=>corpse.State==CorpseEncounterState.Dormant);yield return new WaitForSeconds(.7f);Check(corpse.CameraDrop<.001f&&Vector3.Distance(p.view.transform.position,p.nightCameraAnchor.position)<.01f,"successful resistance restores camera without modifying its normal anchor");Check(corpse.RemainingDormant>19&&corpse.RemainingDormant<=30,"corpse success uses configurable randomized cooldown");
  yield return new WaitForSeconds(.1f);Check(corpse.ForceStartEncounter(),"corpse can begin another encounter for standing-state validation");director.window.panel.SetOpenAmount(1);Check(p.nightExcursion.TryLeaveBed(),"corpse warning safely permits getting out to close the window");yield return Wait(()=>p.NightStanding&&!p.IsTransitioning);float elapsed=corpse.StateElapsed;yield return Keys(UnityEngine.InputSystem.Key.Q);yield return new WaitForSeconds(.4f);Check(corpse.StateElapsed==elapsed&&!corpse.InputActive&&!corpse.BlocksOtherDefenses,"out-of-bed corpse progression and Q are safely paused");yield return Keys();Check(p.nightExcursion.TryReturnToBed(),"returning from corpse pause keeps the existing bed interaction");yield return Wait(()=>p.CanUseNightActions);Check(corpse.State==CorpseEncounterState.Beckoning,"return preserves deferred corpse encounter state");corpse.ResetEncounter();
  yield return new WaitForSeconds(.1f);Check(corpse.ForceStartEncounter(),"rapid Q tapping test starts");yield return Wait(()=>corpse.State==CorpseEncounterState.Reaching);yield return Aim(corpse.head.position);int successes=corpse.SuccessfulDefenses;for(int tap=0;tap<6;tap++){yield return Keys(UnityEngine.InputSystem.Key.Q);yield return new WaitForSeconds(.15f);yield return Keys();}Check(corpse.SuccessfulDefenses==successes&&corpse.ResistanceProgress==0&&corpse.PullProgress>.2f,"rapid Q tapping cannot complete resistance or stall committed danger");corpse.ResetEncounter();
